input.script:
const pkg = JSON.parse(await read('package.json'))
const cfgs = await glob({ pattern: 'vitest.config.*' })
const cfgs2 = await glob({ pattern: 'vite.config.*' })
return { test: pkg.scripts.test, dev: pkg.devDependencies, cfgs, cfgs2 }

const out = {}
for (const p of ['node_modules/vitest/package.json', 'node_modules/vite/package.json', 'node_modules/@vitest/runner/package.json']) {
  try { const j = JSON.parse(await read(p)); out[p] = j.version } catch (e) { out[p] = 'missing' }
}
out.cfg = await read('vitest.config.mts')
return out

